import{_ as a,o as s,c as n,ag as e}from"./chunks/framework.CmaAMB6e.js";const g=JSON.parse('{"title":"07 · 分布式缓存","description":"","frontmatter":{"概念":"分布式缓存","技能":"system-design","阶段":"2-基础组件","状态":"⬜未开始","更新日期":"2026-08-01T00:00:00.000Z","前置":"06 消息队列","耗时":"1.5~2 小时"},"headers":[],"relativePath":"system-design/concepts/07-distributed-cache.md","filePath":"system-design/concepts/07-distributed-cache.md","lastUpdated":null}'),d={name:"system-design/concepts/07-distributed-cache.md"};function i(r,t,l,p,o,h){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="_07-·-分布式缓存" tabindex="-1">07 · 分布式缓存 <a class="header-anchor" href="#_07-·-分布式缓存" aria-label="Permalink to &quot;07 · 分布式缓存&quot;">​</a></h1><blockquote><p><strong>前置</strong>：06 消息队列 · <strong>预计</strong>：1.5~2 小时</p></blockquote><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>缓存是系统性能的<strong>第一杠杆</strong>：把「每次都要算的结果」变成「算一次、读 N 次」。分布式缓存（以 Redis 为代表）把缓存从「进程内的变量」升级为「所有服务共享的独立组件」，让任何服务都能以毫秒级延迟读到热点数据，数据库的读压力可以降低一个数量级。</p><p>对前端工程师来说，缓存并不陌生：浏览器 HTTP 缓存（Cache-Control/ETag）、React Query 的服务端状态缓存、SWR 的 stale-while-revalidate——思路完全一致，只是「缓存放哪、谁失效、怎么保持一致」的答案不同。<strong>前端的缓存是单用户的（不用考虑多进程共享），后端缓存是多用户多服务共享的</strong>——这就是分布式缓存复杂度的来源。</p><p>本章覆盖：缓存分层（本地 vs 集中）、四种缓存策略、Redis 高可用集群、缓存一致性（更新顺序）、以及三个经典故障——穿透、击穿、雪崩。核心心智：<strong>缓存一致性没有银弹，只有「接受最终一致」与「用失效换一致」之间的权衡</strong>。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><h4 id="_1-缓存分层-本地缓存-vs-集中缓存" tabindex="-1">1. 缓存分层：本地缓存 vs 集中缓存 <a class="header-anchor" href="#_1-缓存分层-本地缓存-vs-集中缓存" aria-label="Permalink to &quot;1. 缓存分层：本地缓存 vs 集中缓存&quot;">​</a></h4><table tabindex="0"><thead><tr><th>维度</th><th>本地缓存（进程内）</th><th>集中缓存（Redis）</th></tr></thead><tbody><tr><td>延迟</td><td>纳秒级（内存读取）</td><td>微秒~毫秒级（一次网络往返）</td></tr><tr><td>容量</td><td>单进程内存，几 GB</td><td>集群可达 TB 级</td></tr><tr><td>一致性</td><td>多实例各自缓存 → 互相不一致</td><td>全局一份，天然一致</td></tr><tr><td>故障影响</td><td>进程重启即丢</td><td>独立组件，服务重启不影响</td></tr><tr><td>典型场景</td><td>配置、字典表、不可变数据</td><td>热点数据、session、计数器</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>两级缓存架构（本地为主，Redis 为后备）：</span></span>
<span class="line"><span>  请求 → 本地缓存（命中：0.1ms，未命中 ↓）</span></span>
<span class="line"><span>              → Redis（命中：1ms，未命中 ↓）</span></span>
<span class="line"><span>                  → 数据库（10ms）→ 写回两级缓存</span></span></code></pre></div><p>权衡：本地缓存快但<strong>一致性难保证</strong>（每台机器一份，更新要广播失效）；Redis 一致性好但多一次网络。常见组合：<strong>本地缓存放「几乎不变」的数据（配置/字典），Redis 放「频繁变」的共享数据</strong>。</p><h4 id="_2-缓存策略-四种主流模式" tabindex="-1">2. 缓存策略：四种主流模式 <a class="header-anchor" href="#_2-缓存策略-四种主流模式" aria-label="Permalink to &quot;2. 缓存策略：四种主流模式&quot;">​</a></h4><table tabindex="0"><thead><tr><th>策略</th><th>流程</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>Cache-Aside（旁路）</td><td>读未命中→查库→写缓存；写时直接更新库+删缓存</td><td>实现简单、最常用</td><td>缓存与库短暂不一致</td></tr><tr><td>Read-Through</td><td>读未命中由缓存组件自己回源</td><td>应用代码简单</td><td>回源逻辑耦合缓存</td></tr><tr><td>Write-Through</td><td>写库同时写缓存</td><td>缓存永远新鲜</td><td>写放大，写频繁场景亏</td></tr><tr><td>Write-Behind</td><td>写库，缓存异步延迟写</td><td>写性能极高</td><td>缓存宕机丢更新，风险大</td></tr></tbody></table><p><strong>Cache-Aside 是默认选择</strong>，其他模式各有权衡：Write-Through 适合「读多且写入必须立刻可见」，Write-Behind 适合「可以接受丢失的写」——记住：<strong>没有免费的写优化，延迟写 = 丢数据风险换性能</strong>。</p><h4 id="_3-redis-高可用集群" tabindex="-1">3. Redis 高可用集群 <a class="header-anchor" href="#_3-redis-高可用集群" aria-label="Permalink to &quot;3. Redis 高可用集群&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Redis 主从 + 哨兵（Sentinel）：故障时自动切换主从</span></span>
<span class="line"><span>  客户端 → 哨兵集群（发现当前主节点）→ 主节点 → 从节点（异步复制）</span></span>
<span class="line"><span>  主节点宕机 → 哨兵选新主 → 客户端重新指向</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Redis Cluster（分片集群）：</span></span>
<span class="line"><span>  16384 个哈希槽（slot）分布在多个主节点上</span></span>
<span class="line"><span>  key 的 CRC16 哈希 → 槽 → 节点；读写打点取数，支持自动分片与转移</span></span>
<span class="line"><span>  每个主节点配一个从节点做数据冗余</span></span></code></pre></div><p>选型权衡：<strong>哨兵模式</strong>适合数据量 &lt; 单机内存、需要高可用；<strong>Cluster 模式</strong>适合数据量超过单机、需要水平扩展。数据量没超单机却上 Cluster，是典型的过度设计。</p><h4 id="_4-缓存一致性-先更新库还是先更新缓存" tabindex="-1">4. 缓存一致性：先更新库还是先更新缓存 <a class="header-anchor" href="#_4-缓存一致性-先更新库还是先更新缓存" aria-label="Permalink to &quot;4. 缓存一致性：先更新库还是先更新缓存&quot;">​</a></h4><p>经典的顺序问题。以「修改用户资料」为例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>方案 A：先更新缓存，再更新数据库</span></span>
<span class="line"><span>  缓存更新成功 → 数据库更新失败 → 缓存是新的，库是旧的</span></span>
<span class="line"><span>  → 读全部打到缓存，直到过期——长期不一致（严重）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>方案 B：先更新数据库，再删除缓存（Cache-Aside 标准做法）</span></span>
<span class="line"><span>  更新库成功 → 删缓存失败 → 缓存还是旧的</span></span>
<span class="line"><span>  → 下次读打到旧缓存，直到「下一次」写入再次删缓存 → 短暂不一致（可接受）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>方案 C：先更新数据库，再延迟双删（删缓存 → 等 1s → 再删一次）</span></span>
<span class="line"><span>  解决「读未命中回源写入旧值」的竞态窗口 → 业界常见兜底</span></span></code></pre></div><p>权衡结论：<strong>更新顺序选「先库后删缓存」</strong>，一致性风险从「长期错误」降为「短暂陈旧」，再配合 TTL 兜底（缓存总有到期时间，不会永远错）。追求更强一致性（如强一致读）则<strong>绕过缓存直接读库</strong>——这本身就是一种「用性能换正确」的权衡。</p><h4 id="_5-三大经典故障-穿透、击穿、雪崩" tabindex="-1">5. 三大经典故障：穿透、击穿、雪崩 <a class="header-anchor" href="#_5-三大经典故障-穿透、击穿、雪崩" aria-label="Permalink to &quot;5. 三大经典故障：穿透、击穿、雪崩&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>缓存穿透：查询一个【根本不存在】的 key</span></span>
<span class="line"><span>  → 每次都不命中缓存，直接打到数据库（恶意攻击：用随机 id 狂扫）</span></span>
<span class="line"><span>  解决：① 空值也缓存（TTL 短）；② 布隆过滤器（不存在直接挡掉）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>缓存击穿：一个【热点 key 恰好在过期瞬间】被大量请求同时访问</span></span>
<span class="line"><span>  → 全部同时回源打库，数据库被打垮</span></span>
<span class="line"><span>  解决：① 互斥锁（只让一个请求回源，其余等待）；② 热点 key 永不过期 + 异步刷新</span></span>
<span class="line"><span></span></span>
<span class="line"><span>缓存雪崩：【大批 key 同一时间集体过期】（或 Redis 宕机）</span></span>
<span class="line"><span>  → 大量请求同时回源，数据库直接宕机</span></span>
<span class="line"><span>  解决：① 过期时间加随机值（防集中）；② 多级缓存（本地兜底）；</span></span>
<span class="line"><span>       ③ Redis 宕机时限流/降级（直接返回旧数据或排队）</span></span></code></pre></div><p>三个故障的本质都是「<strong>缓存失效瞬间的流量全部冲向数据库</strong>」，解决思路统一为「错峰 + 兜底 + 挡墙」：错峰（随机 TTL）、兜底（本地缓存/旧数据）、挡墙（布隆过滤器/互斥锁/限流）。</p><h4 id="_6-缓存监控-先于故障发现" tabindex="-1">6. 缓存监控：先于故障发现 <a class="header-anchor" href="#_6-缓存监控-先于故障发现" aria-label="Permalink to &quot;6. 缓存监控：先于故障发现&quot;">​</a></h4><p>缓存出问题往往是「静默恶化」，监控是唯一能提前发现的手段：</p><table tabindex="0"><thead><tr><th>指标</th><th>健康值参考</th><th>异常信号</th></tr></thead><tbody><tr><td>命中率（hit rate）</td><td>读多系统 &gt; 90%</td><td>跌破 80%：缓存键设计或淘汰策略有问题</td></tr><tr><td>大 key（&gt; 1 MB）</td><td>无</td><td>单 key 过大拖垮网络与内存</td></tr><tr><td>慢命令（&gt; 10 ms）</td><td>无</td><td>排查 O(N) 命令（KEYS、大集合操作）</td></tr><tr><td>内存使用率</td><td>&lt; 70%</td><td>逼近上限触发 LRU 淘汰风暴，命中率骤降</td></tr><tr><td>过期淘汰率（evicted）</td><td>平稳</td><td>突增 = 数据量大增或 TTL 设太短</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>命中率是缓存系统的「血压」：</span></span>
<span class="line"><span>  命中率 = 缓存命中的读次数 / 总读次数</span></span>
<span class="line"><span>  命中率从 95% 掉到 85% → 数据库读压力直接翻倍</span></span>
<span class="line"><span>  → 排查顺序：① 缓存键是否带动态参数？② TTL 是否被改短？</span></span>
<span class="line"><span>    ③ 是否有批量删除？④ 是否有大促流量激增？</span></span></code></pre></div><p><strong>监控的价值是把「缓存失效」从事故变成报表</strong>——命中率报表每天看，而不是等数据库告警了才回头看缓存。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>缓存没有 TTL</strong>：一致性全靠「删缓存」这个动作，删失败就永远错；TTL 是最后的兜底防线。</li><li><strong>缓存了不该缓存的强一致数据</strong>：余额、库存这类数据放进普通缓存，一旦不一致就是资损；强一致数据应读库或用带锁的方案。</li><li><strong>热点 key 忽略「击穿」</strong>：只有 1 个 key 但 QPS 10 万，过期瞬间就雪崩；互斥锁或永不过期 + 异步刷新是标配。</li><li><strong>穿透场景没有空值缓存</strong>：恶意扫不存在 id，数据库被白打；布隆过滤器 + 空值缓存一起上。</li><li><strong>把缓存当存储</strong>：Redis 存「绝不能丢」的数据，主从切换时丢更新；Redis 是缓存，持久化的责任属于数据库。</li><li><strong>监控缺位</strong>：不监控命中率、大 key、慢命令，缓存问题爆发时无从定位；命中率跌到 50% 以下就要查代码。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>：用 Redis 实现 Cache-Aside：读用户资料未命中回源数据库（可用内存模拟）再写缓存，修改资料后「先更新库再删缓存」，验证 TTL 兜底行为。</li><li><strong>进阶</strong>：模拟三个故障并给出方案：用脚本制造「批量 key 同时过期」，验证随机 TTL 的效果；实现布隆过滤器挡住穿透请求。</li><li><strong>综合</strong>：设计一个商品详情页的缓存方案：本地缓存（基本信息）+ Redis（详情 + 库存）+ 数据库，画出三级缓存与失效流程，说明热点商品（爆款）如何防击穿、大促时如何防雪崩。</li></ol><blockquote><p>用 <code>/practice system-design 分布式缓存</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端架构概念</th><th>系统设计对应</th></tr></thead><tbody><tr><td>浏览器 HTTP 缓存（Cache-Control/ETag）</td><td>Redis 缓存（TTL 控制失效）</td></tr><tr><td>SWR / stale-while-revalidate</td><td>Cache-Aside：先展示旧数据再后台刷新</td></tr><tr><td>React Query 缓存 + 失效重取</td><td>先更新库再删缓存</td></tr><tr><td>页面缓存击穿（热门页首屏直出）</td><td>热点 key 击穿 + 互斥锁</td></tr><tr><td>本地状态（组件内 state）</td><td>本地缓存（进程内，快但不共享）</td></tr><tr><td>全局状态（Store，跨组件共享）</td><td>集中缓存（Redis，跨服务共享）</td></tr><tr><td>清缓存强刷（Cmd+Shift+R）</td><td>删缓存/主动失效</td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://redis.io/docs/" target="_blank" rel="noreferrer">Redis 官方文档（含 Cluster 与缓存模式）</a></li><li><a href="https://aws.amazon.com/caching/" target="_blank" rel="noreferrer">Amazon 缓存策略白皮书（Caching strategies）</a></li><li><a href="https://martinfowler.com/bliki/TwoHardThings.html" target="_blank" rel="noreferrer">Martin Fowler：Cache Aside 等缓存策略模式</a></li></ul>`,38)])])}const b=a(d,[["render",i]]);export{g as __pageData,b as default};
